<!doctype html><html <?php language_attributes(); ?>><head><meta charset="<?php bloginfo('charset'); ?>"><meta name="viewport" content="width=device-width,initial-scale=1"><?php wp_head(); ?></head><body <?php body_class(); ?>><?php wp_body_open();$w=xdj_words(); ?><a class="skip" href="#main">Skip to content</a><div class="notice">小当家 · ONE STEP GROUP <span><?php echo esc_html($w[5]); ?></span></div><header><a class="brand" href="<?php echo esc_url(function_exists('pll_home_url')?pll_home_url():home_url('/')); ?>"><img class="brand-logo" src="<?php echo esc_url(get_theme_file_uri('assets/logo.png')); ?>" alt="小當家 · One Step Group" width="682" height="412"></a><nav aria-label="Navigation"><ul><?php foreach(['services'=>1,'markets'=>2,'about'=>3] as $key=>$i):?><li><a href="<?php echo esc_url(xdj_page_url($key)); ?>"><?php echo esc_html($w[$i]); ?></a></li><?php endforeach;?></ul></nav><a class="button small" href="<?php echo esc_url(xdj_page_url('contact')); ?>"><?php echo esc_html($w[4]); ?> ↗</a><div class="language-switcher"><label for="site-language">Language</label><select id="site-language" onchange="if(this.value) location.href=this.value"><?php if(function_exists('pll_the_languages'))foreach(pll_the_languages(['raw'=>1,'hide_if_empty'=>0]) as $l):if(!in_array($l['slug'],['zh-hans','zh-hant','en','fr','de','it','es'],true))continue;?><option value="<?php echo esc_url($l['url']); ?>" <?php selected($l['current_lang']); ?>><?php echo esc_html($l['name']); ?></option><?php endforeach;?></select></div></header>
